window.VAULT={"version":2,"tags":["Scaling","Latency","Databases","Sharding","Migration","Caching","Consistency","Transactions","Messaging","Reliability","APIs","Observability","Operations","Architecture","Leadership","Cost & compliance"],"categories":[{"id":"scale","name":"Scale & Traffic","topics":["Request path & scaling basics","Monolith vs services","Overload, backpressure & spikes","Sync, async & queues"]},{"id":"data","name":"Data & Storage","topics":["SQL, NoSQL & OLTP vs OLAP","Partitioning & hot keys","Indexing","Migrations & backfills","Retention & deletion","Multi-tenancy"]},{"id":"caching","name":"Caching & Performance","topics":["Caching strategy","Pagination"]},{"id":"consistency","name":"Consistency & Transactions","topics":["Idempotency","Consistency models & CAP","Distributed transactions & reconciliation","Consensus & distributed IDs"]},{"id":"reliability","name":"Reliability & Failure","topics":["Failure modes & degradation","Retries, breakers & bulkheads","Multi-region & outages","Releases & rollback","SLOs","Recovery"]},{"id":"streaming","name":"Streaming & Async","topics":["Event-driven design","Delivery semantics","Poison messages & dead letters","Ordering","Schedulers & long-running jobs","Event schema evolution"]},{"id":"apis","name":"APIs & Boundaries","topics":["Service boundaries & gateway","Versioning, compatibility & deprecation","Rate limits & quotas","Partial failure"]},{"id":"observability","name":"Observability & Operations","topics":["Logging & tracing","Metrics, dashboards & alerts","Latency debugging","Runbooks & failure drills"]},{"id":"evolution","name":"Evolution, Cost & Trade-offs","topics":["MVP, platforms & cost","Build vs buy","Extensibility, experiments & compliance","Legacy migration"]},{"id":"judgment","name":"Judgment & Leadership","topics":["Trade-offs & design reviews","Simplicity & over/under-engineering","Design docs & ownership"]}],"questions":[{"id":"walk-one-request-dns-database","cat":"scale","topic":"Request path & scaling basics","level":"fundamental","source":"both","q":"Walk one request from DNS to the database and back. Where does each millisecond go?","also":["How does a request flow end-to-end through a production system?"],"a":["Name every hop: DNS, TLS, CDN or edge, load balancer, service, cache, database. Give each hop a latency budget, then say which hops dominate p99 and why.","DNS, edge or CDN, load balancer, gateway, service, cache, datastore, and back. State what each hop does, what can fail there, and where latency accumulates."],"tags":["Latency"],"legacy":[0,93]},{"id":"read-traffic-grows-10x-one","cat":"scale","topic":"Request path & scaling basics","level":"intermediate","source":"both","q":"Read traffic grows 10x in one quarter. What do you change first, and what do you refuse to change?","also":["How do I design a service that can handle 10x more traffic with minimal changes?"],"a":["Measure the bottleneck before acting. Cache and add read replicas before sharding. Hold the API contract and data model steady so clients and teams do not have to move.","Stateless services behind a load balancer, caching for hot reads, replicas, partitionable data, and autoscaling with tested limits. Find the first bottleneck by load testing, not guessing."],"tags":["Scaling","Caching"],"legacy":[1,94]},{"id":"choose-load-balancing-strategy-long","cat":"scale","topic":"Request path & scaling basics","level":"intermediate","source":"mine","q":"Choose a load balancing strategy for long-lived connections versus short RPCs.","also":[],"a":["Round robin, least-request, power of two choices, consistent hashing. Connection draining, slow start for new instances, and what happens to sticky state on scale-in."],"tags":["Scaling","Latency"],"legacy":[4]},{"id":"size-system-50-000-requests","cat":"scale","topic":"Request path & scaling basics","level":"advanced","source":"mine","q":"Size a system for 50,000 requests per second with a 100 ms hard deadline.","also":[],"a":["Back-of-envelope CPU, memory and network per request. Fan-out cost, timeout budget split across calls, 30 to 40 percent headroom, and what you drop when the deadline is about to be missed."],"tags":["Scaling","Latency"],"legacy":[5]},{"id":"trade-offs-between-vertical-horizontal","cat":"scale","topic":"Request path & scaling basics","level":"fundamental","source":"ref","q":"What are the trade-offs between vertical and horizontal scaling?","also":[],"a":["Vertical is simple and has a ceiling and a single point of failure. Horizontal needs statelessness or partitioning, adds coordination cost, and scales further. Most systems do vertical first, then horizontal where the data allows."],"tags":["Scaling"],"legacy":[48]},{"id":"splitting-monolith-pay-itself","cat":"scale","topic":"Monolith vs services","level":"intermediate","source":"both","q":"When does splitting a monolith pay for itself?","also":["How do I decide when to split a monolith into services?"],"a":["Team ownership lines, different deploy cadence, different scaling profiles. Price in the costs: network failure modes, distributed data, on-call load. A modular monolith is a valid answer.","Split along team and data ownership lines when deploy independence or scaling needs diverge. Cost: network failures, distributed data, operational load. A modular monolith may be enough."],"tags":["Scaling","Architecture"],"legacy":[2,92]},{"id":"design-admission-control-service-stays","cat":"scale","topic":"Overload, backpressure & spikes","level":"advanced","source":"both","q":"Design admission control so a service stays up through a 20x spike.","also":["How do I protect downstream services from traffic spikes?"],"a":["Shed by priority, bound every queue, use adaptive concurrency limits, apply per-tenant quotas, and fail fast with Retry-After. Protect the critical path first, batch work last.","Rate limits and concurrency caps at the caller, queues that smooth bursts, circuit breakers, load shedding by priority, and caching in front of the dependency."],"tags":["Scaling","Reliability"],"legacy":[3,95]},{"id":"design-backpressure-high-traffic-system","cat":"scale","topic":"Overload, backpressure & spikes","level":"advanced","source":"ref","q":"How do I design for backpressure in a high-traffic system?","also":[],"a":["Bounded queues, propagate pressure upstream (blocking, credits, 429s), shed load deliberately, and size consumers to drain bursts. Unbounded buffers only move the failure later."],"tags":["Reliability","Scaling"],"legacy":[51]},{"id":"choose-between-synchronous-asynchronous-communication","cat":"scale","topic":"Sync, async & queues","level":"intermediate","source":"ref","q":"How do I choose between synchronous and asynchronous communication?","also":[],"a":["Synchronous when the caller needs the answer to proceed and latency is bounded. Asynchronous to decouple availability, absorb bursts and run slow work. Cost of async: eventual results, retries, duplicate handling."],"tags":["Messaging"],"legacy":[49]},{"id":"should-use-queue-versus-direct","cat":"scale","topic":"Sync, async & queues","level":"intermediate","source":"ref","q":"When should I use a queue versus direct RPC?","also":[],"a":["Queue for buffering, fan-out, retries and independent consumer speed. RPC for request-scoped answers with a tight deadline. Never put a queue in a path that needs a synchronous response without a reply mechanism."],"tags":["Messaging"],"legacy":[50]},{"id":"boundary-between-oltp-olap-data","cat":"data","topic":"SQL, NoSQL & OLTP vs OLAP","level":"fundamental","source":"mine","q":"Where is the boundary between OLTP and OLAP, and how does data cross it?","also":[],"a":["Row store for transactions, columnar store for analytics. Move data by change data capture, not dual writes. Cover lag, backfill, and schema drift between the two sides."],"tags":["Databases"],"legacy":[8]},{"id":"decide-between-sql-nosql-search","cat":"data","topic":"SQL, NoSQL & OLTP vs OLAP","level":"fundamental","source":"ref","q":"How do I decide between SQL, NoSQL, and search engines?","also":[],"a":["Start from access patterns and consistency needs. Relational for transactions and ad hoc queries, key-value or wide-column for known-key scale, search engines for text and faceting as a derived index, never the source of truth."],"tags":["Databases"],"legacy":[53]},{"id":"model-data-differently-oltp-versus","cat":"data","topic":"SQL, NoSQL & OLTP vs OLAP","level":"fundamental","source":"ref","q":"How do I model data differently for OLTP versus OLAP workloads?","also":[],"a":["OLTP: normalized rows, narrow transactions, point lookups. OLAP: denormalized wide tables or star schemas in columnar storage, loaded from OLTP by change data capture or batch."],"tags":["Databases"],"legacy":[96]},{"id":"pick-partition-key-multi-tenant","cat":"data","topic":"Partitioning & hot keys","level":"intermediate","source":"both","q":"Pick a partition key for a multi-tenant ledger, then show how it fails.","also":["What does a good partition key look like in a distributed store?"],"a":["Tenant, account or time as candidates. Failure cases: one giant tenant, time-based hot tail, cross-partition queries. Mitigate with composite keys, salting for heavy keys, and a resharding plan.","High cardinality, even access, aligned with the dominant query, and stable over time. Avoid monotonically increasing keys that create a hot tail."],"tags":["Sharding","Databases"],"legacy":[6,97]},{"id":"hot-partition-shows-up-2","cat":"data","topic":"Partitioning & hot keys","level":"advanced","source":"both","q":"A hot partition shows up at 2 a.m. Diagnose it and fix it without downtime.","also":["How do I avoid hot partitions and skew?"],"a":["Confirm skew from per-partition metrics. Short-term: cache the hot key, rate limit, split the range. Long-term: change the key, add a salt, rebalance online. Say how you verify the fix.","Choose a well-distributed key, salt or split heavy keys, cache hot reads, and monitor per-partition load so skew is seen before it becomes an outage."],"tags":["Sharding","Operations","Databases"],"legacy":[7,98],"answer":{"thesis":"Prove it's skew and find the key, buy time with the cheapest mitigation aimed at that key, then fix the key design online. Don't start by adding capacity: a hot key stays on one partition however many nodes you add.","pitch":"At 2 a.m. I'm mitigating, not redesigning. First I confirm from per-partition metrics that one partition is saturated while the rest are mostly idle; that rules out general overload. Then I find the hot key from top-key sampling or access logs and work out why it's hot: one huge tenant, a client stuck in a retry loop, a viral item, or a monotonically increasing key piling writes onto the newest range. The mitigation targets that key: rate-limit or block the offending client, put a short-TTL cache in front of hot reads, or split the range if the store supports it. Once things are stable, the real fix is the key design (a composite key, salting only the heavy keys, or moving a giant tenant to dedicated partitions), rolled out with dual writes and an online backfill. I call it fixed when the per-partition load distribution has flattened, not just when errors stop.","points":[{"h":"Confirm it's skew, not overload","d":"Look at per-partition throughput, latency and throttling. Skew looks like one partition at its limit while the cluster average is low. Cluster-level dashboards hide it: a 30% average can contain one partition at 100%."},{"h":"Find the key and the cause","d":"Use whatever the store offers for top keys (key sampling, per-partition metrics, consumer lag per partition) plus access logs. Typical causes: one very large tenant, a retry storm from one client, a celebrity item, or timestamp and auto-increment keys concentrating writes at the tail of the range."},{"h":"Mitigate in minutes","d":"Hot reads: cache in front with a short TTL and request coalescing. Hot writes: rate-limit the offender, queue or shed non-critical writes, or flip a feature flag that turns off the trigger. If the store can split a range or rebalance automatically, let it or force it."},{"h":"Protect everyone else on that partition","d":"Isolate the hot tenant or client (bulkhead, per-tenant limits) so the other tenants sharing the partition recover first. Post status updates in the incident channel while you work."},{"h":"Fix the key shape","d":"Options: a composite key such as (tenant, entity) instead of (tenant); salt only the heavy keys with N suffixes and scatter-gather on read; prefix time-based keys with a hash bucket; give giant tenants dedicated partitions or cells."},{"h":"Migrate without downtime","d":"Dual-write to the new key layout, backfill with throttling, verify with counts and checksums, switch reads, then stop writing the old layout. Changing a partition key in place is usually a full rewrite, so treat it as a migration."},{"h":"Verify and prevent","d":"Watch the ratio of the hottest partition to the median until it flattens. Add alerts on per-partition saturation, track top tenants by load, and load test with skewed traffic instead of uniform."}],"decision":"Hot reads: cache and replicate. Hot writes: split or salt the key. One tenant hot: isolate the tenant. Keys drifting hot over time (monotonic): change the key shape. Adding nodes doesn't help any of these, because a single key always maps to a single partition.","numbers":["DynamoDB documents a ceiling of 3,000 read units and 1,000 write units per second per partition. A key that needs more is throttled however much capacity the table has.","Salting a heavy key into N buckets divides its per-partition write load by N but multiplies read fan-out by N. With N = 10, one logical read becomes 10 parallel reads, which is why you salt only the heavy keys.","Working heuristic for spotting skew: the hottest partition at its limit while the median sits at a fraction of it, for example 100% against 20%."],"pitfalls":["Scaling out the cluster: the hot key still lives on one partition.","Stopping at the cache: it hides the hot read while the key keeps growing, and the next spike hits writes.","Salting every key instead of only the heavy ones: every read becomes a scatter-gather.","Changing the partition key in place without planning the data rewrite.","Declaring victory when errors stop instead of checking that load per partition has evened out."],"followups":[{"q":"The hot key is a single counter, such as likes on a viral post.","a":"Shard the counter: N sub-counters, write to a random one, sum them on read or aggregate periodically. Accept that the displayed total is slightly stale."},{"q":"How would you have caught this before 2 a.m.?","a":"Alert on per-partition saturation and on the max-to-median ratio, track the top tenants by load over time, and run load tests with skewed (Zipf-like) traffic instead of uniform traffic."},{"q":"The hot tenant is your largest customer. Do you rate-limit them?","a":"Short term, protect everyone else and talk to them. Long term, give them a dedicated cell or partitions so their growth becomes their own capacity, priced accordingly."},{"q":"Walk me through re-keying without downtime.","a":"Expand and contract: dual-write to the new layout, run a throttled and resumable backfill, verify, move reads, stop the old writes, then clean up after a full cycle with no reads on the old layout."}],"example":"A multi-tenant orders table is partitioned by tenant_id. A large retailer runs a flash sale; its partition throttles, failing writes for the 40 smaller tenants that share it. On-call caps the retailer's write rate and queues its non-urgent updates, and the other tenants recover. The follow-up changes the key to (tenant_id, hash bucket of order_id) for tenants above a size threshold, migrated with dual writes over a week.","related":["pick-partition-key-multi-tenant","shard-data-user-tenant-region","migrate-billion-row-table-new","caching-story-hot-keys-large"],"sources":[{"title":"AWS DynamoDB: Designing partition keys to distribute your workload","url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/bp-partition-key-uniform-load.html"},{"title":"AWS DynamoDB: Best practices for partition key design","url":"https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/bp-partition-key-design.html"},{"title":"Martin Kleppmann: Designing Data-Intensive Applications, chapter 6 (Partitioning)","url":"https://dataintensive.net/"}]}},{"id":"shard-data-user-tenant-region","cat":"data","topic":"Partitioning & hot keys","level":"intermediate","source":"ref","q":"How do I shard data by user, tenant, region, or something else?","also":[],"a":["Shard on the dimension most queries filter by and that spreads load evenly. Cover cross-shard queries, rebalancing, and tenant or region affinity for locality and compliance."],"tags":["Sharding","Databases"],"legacy":[54]},{"id":"design-indexes-table-takes-90","cat":"data","topic":"Indexing","level":"intermediate","source":"both","q":"Design indexes for a table that takes 90 percent writes.","also":["How should I index for read-heavy versus write-heavy workloads?"],"a":["Every index taxes writes. Keep the few that serve real queries, prefer covering indexes, consider LSM engines, and push ad hoc reads to a replica or search store.","Read-heavy: more indexes, covering indexes, materialized views. Write-heavy: few indexes, append-friendly storage, deferred or asynchronous secondary structures."],"tags":["Databases"],"legacy":[9,99]},{"id":"migrate-billion-row-table-new","cat":"data","topic":"Migrations & backfills","level":"advanced","source":"both","q":"Migrate a billion-row table to a new schema with zero downtime.","also":["How do I design a migration strategy for a huge table?"],"a":["Expand, dual write, throttled backfill, verify with checksums, shadow reads, cut over, then contract. Keep a rollback path until the old column has been unused for a full cycle.","Expand and contract with dual writes, a throttled resumable backfill, verification before cutover, a rollback window, and cleanup only after the old path is provably idle."],"tags":["Migration","Reliability","Databases"],"legacy":[10,91]},{"id":"safely-backfill-data-production","cat":"data","topic":"Migrations & backfills","level":"advanced","source":"ref","q":"How do I safely backfill data in production?","also":[],"a":["Throttle against production load, make the job idempotent and resumable, process in key ranges, verify with counts and checksums, and keep it observable and stoppable."],"tags":["Migration","Databases"],"legacy":[56]},{"id":"schema-changes-downtime","cat":"data","topic":"Migrations & backfills","level":"advanced","source":"ref","q":"How do I do schema changes without downtime?","also":[],"a":["Expand and contract: add nullable, deploy code that writes both, backfill, switch reads, remove the old. Avoid long locks and test the online DDL path against production-size data."],"tags":["Migration","Databases"],"legacy":[70]},{"id":"design-retention-soft-delete-legal","cat":"data","topic":"Retention & deletion","level":"intermediate","source":"both","q":"Design retention, soft delete and legal erasure so they do not contradict each other.","also":["How do I design soft delete, archival, and retention?"],"a":["Different clocks for each: soft delete for undo, retention for policy, erasure for law. Cover backups, derived stores, logs, and how you prove deletion happened.","Deleted flag or tombstone for undo, tiered storage for old data, retention policies with automated purge, and explicit handling for legal deletion and backups."],"tags":["Cost & compliance","Databases"],"legacy":[11,100]},{"id":"handle-multi-tenant-data-isolation","cat":"data","topic":"Multi-tenancy","level":"intermediate","source":"ref","q":"How do I handle multi-tenant data isolation?","also":[],"a":["Row-level with tenant id on every query and enforced in the data layer, schema per tenant, or database per tenant. Trade isolation strength against cost and operational load. Plan noisy-neighbor controls and tenant export."],"tags":["Sharding","Reliability"],"legacy":[55]},{"id":"should-cache-client-edge-service","cat":"caching","topic":"Caching strategy","level":"fundamental","source":"ref","q":"Where should I cache: client, edge, service, or DB layer?","also":[],"a":["Closer to the user means lower latency and weaker control over invalidation. Match the layer to data volatility and sharing: edge for public static, service for computed results, DB layer for hot rows."],"tags":["Caching","Latency"],"legacy":[57]},{"id":"pick-between-write-through-write","cat":"caching","topic":"Caching strategy","level":"fundamental","source":"ref","q":"How do I pick between write-through, write-back, and write-around caching?","also":[],"a":["Write-through keeps cache and store aligned at write cost. Write-back is fast but risks loss on cache failure. Write-around avoids polluting the cache with data that is rarely read."],"tags":["Caching"],"legacy":[58]},{"id":"design-cache-invalidation-rules-not","cat":"caching","topic":"Caching strategy","level":"intermediate","source":"ref","q":"How do I design cache invalidation rules that do not become a nightmare?","also":[],"a":["Prefer TTLs with jitter plus event-driven invalidation for the few cases that need it. Version keys instead of deleting, keep key construction in one place, and accept bounded staleness explicitly."],"tags":["Caching"],"legacy":[59]},{"id":"handle-cache-stampede-thundering-herd","cat":"caching","topic":"Caching strategy","level":"intermediate","source":"ref","q":"How do I handle cache stampede and thundering herd?","also":[],"a":["Request coalescing so one caller rebuilds, stale-while-revalidate, TTL jitter, early refresh, and a lock or lease with a short timeout."],"tags":["Caching","Reliability"],"legacy":[60]},{"id":"caching-story-hot-keys-large","cat":"caching","topic":"Caching strategy","level":"intermediate","source":"ref","q":"What is my caching story for hot keys and large objects?","also":[],"a":["Replicate hot keys across nodes or add a local near-cache, split large values, compress, and cap object size. Watch for one key saturating one cache shard."],"tags":["Caching","Scaling"],"legacy":[61]},{"id":"measure-whether-cache-actually-helping","cat":"caching","topic":"Caching strategy","level":"fundamental","source":"ref","q":"How do I measure whether a cache is actually helping?","also":[],"a":["Hit ratio by key class, latency with and without, origin load saved, eviction rate, and cost per hit. A high hit ratio on cheap reads can still be pointless."],"tags":["Caching","Observability"],"legacy":[62]},{"id":"design-pagination-massive-datasets-efficiently","cat":"caching","topic":"Pagination","level":"intermediate","source":"ref","q":"How do I design pagination for massive datasets efficiently?","also":[],"a":["Keyset (cursor) pagination over offset, a stable sort key with a tiebreaker, bounded page size, and a plan for results that change between pages."],"tags":["Databases","Scaling"],"legacy":[63]},{"id":"build-idempotency-write-api-clients","cat":"consistency","topic":"Idempotency","level":"advanced","source":"both","q":"Build idempotency for a write API that clients and your own gateway can both retry.","also":["How do I handle idempotency for write APIs?"],"a":["Client-supplied key, atomic claim of the key with the write, stored response for replays, key expiry, and the in-flight duplicate case. Say what you do when the request body differs.","Idempotency key per logical operation, atomically recorded with the write, replayed response on duplicates, a defined behavior for a duplicate that arrives while the first is still running, and key expiry."],"tags":["Consistency","APIs","Databases"],"legacy":[13,90],"answer":{"thesis":"The client names each logical operation with an idempotency key; the server records that key atomically with the effect and replays the stored result for any repeat. Everything else is handling the edges of that one rule.","pitch":"I'd require an Idempotency-Key header on every mutating endpoint, generated by the client once per logical operation and reused on every retry. On the server, the first request inserts the key, scoped to the account and stored with a hash of the request, in the same transaction as the business write; when it finishes we store the response. A retry with a finished key gets that stored response replayed. A retry that arrives while the original is still running gets a 409 with Retry-After instead of running twice. The same key with a different body is a 422, because that's a client bug, not a retry. Keys live longer than the longest client retry window, typically 24 hours. The gateway forwards the key and never mints one, or every gateway retry would look like a new operation.","points":[{"h":"One key per logical operation, owned by the client","d":"Generated before the first attempt (a UUID is fine) and persisted client-side, so a retry after an app restart reuses it. SDK and gateway retries pass the key through. If the gateway generated keys, its own retries would each look new and dedupe would never fire."},{"h":"Scope and fingerprint the key","d":"Make (account_id, key) unique, not the key alone, so tenants can't collide or see each other's responses. Store a hash of method, path and canonical body so a reused key with different parameters is detected and rejected."},{"h":"Claim the key atomically with the effect","d":"Insert the key row with status 'started' in the same database transaction as the business write. The unique constraint makes a concurrent duplicate lose. Either the effect and the key both commit, or neither does, so a crash can't leave a half-applied operation."},{"h":"Replay what executed; don't save what never ran","d":"Once execution has started, store the status code and body (including failures produced during execution) and return them byte-for-byte on a repeat. Requests rejected before execution, such as validation errors or a concurrent conflict, are not saved, so the client can fix the request and retry with the same key."},{"h":"Handle the in-flight duplicate explicitly","d":"If the key exists with status 'started', return 409 Conflict with Retry-After rather than waiting or running again. If a 'started' row is older than a takeover timeout, a later retry may resume it, guarded by a version check so two takeovers can't both proceed."},{"h":"External side effects need recovery points","d":"A card charge or an email can't join your database transaction. Model the request as a state machine (started, charge_requested, charged, completed), commit progress between steps, and pass a key derived from the client's key to the provider so it dedupes too. A retry resumes from the last recovery point."},{"h":"Expire keys deliberately","d":"Keep keys longer than the longest client retry horizon, then purge. After expiry the same key is a new operation; document that so clients don't retry days later and get charged again."}],"decision":"If the effect is a write in one database, claim the key and write in a single transaction: simplest and correct. If the effect is external, use the recovery-point state machine plus a downstream idempotency key. If the operation can be made naturally idempotent (PUT of full state, conditional write on a version, set-based update), do that and skip the key store entirely.","numbers":["Key storage ≈ writes/day × bytes per key × retention days. At 5M writes/day, about 1 KB per key (key, request hash, stored response) and 1 day of retention: about 5 GB, small enough to live in the primary database.","Latency cost of the same-database design is one extra indexed insert inside a transaction you already run. A separate key store adds a network round trip per write and, worse, a window where the key and the effect can disagree."],"pitfalls":["Recording the key after the side effect: a crash in between means the retry applies the effect twice.","Letting the gateway or load balancer generate keys: every retry gets a fresh key and nothing is deduplicated.","Saving a transient failure (timeout, 503 from a dependency) as the final result: that key can now never succeed.","Making keys globally unique instead of per account: one tenant's key can collide with another's or return their response.","Expiry shorter than the client's retry window, for example a mobile app that retries after hours offline.","Keys in a separate store such as a cache, with no transaction spanning it and the write: the double-apply window is back."],"followups":[{"q":"The idempotency store is down. Do you fail open or closed?","a":"If keys live in the same database as the write, the question disappears: no database means no write. With a separate store, fail closed for money movement (return 503 and let the client retry) and fail open only for low-risk writes that are deduplicated downstream. Say which and why."},{"q":"Two requests with the same key arrive 5 ms apart on different servers.","a":"The unique constraint on (account_id, key) decides. One insert wins; the other hits the conflict and returns 409 with Retry-After. No distributed lock is needed when the database enforces uniqueness."},{"q":"How does this extend to a saga across several services?","a":"Derive child keys deterministically from the parent key plus the step name, for example parent:reserve-stock. Every step is idempotent on its own, and replaying the saga hits the same keys."},{"q":"What changes in an active-active, multi-region setup?","a":"Uniqueness has to be enforced in one place per key. Pin each account's writes to a home region, which account-scoped keys make natural, or accept a cross-region dedupe window and run a reconciliation job."}],"example":"A mobile app sends POST /payments with key k1. The server commits the charge, but the response is lost when the phone switches networks. The app retries with k1 a few seconds later; the server finds k1 completed and replays the original 201 with the same payment id. The user is charged once and sees one payment.","related":["replace-two-phase-commit-across","design-outbox-inbox-pattern-reliable","retries-amplifying-outage-design-retries","exactly-once-practice-kafka-flink"],"sources":[{"title":"Stripe API reference: Idempotent requests","url":"https://docs.stripe.com/api/idempotent_requests"},{"title":"Brandur Leach: Implementing Stripe-like idempotency keys in Postgres","url":"https://brandur.org/idempotency-keys"},{"title":"IETF draft: The Idempotency-Key HTTP header field","url":"https://datatracker.ietf.org/doc/draft-ietf-httpapi-idempotency-key-header/"}]}},{"id":"eventual-consistency-acceptable-payments-flow","cat":"consistency","topic":"Consistency models & CAP","level":"fundamental","source":"both","q":"Where is eventual consistency acceptable in a payments flow, and where is it never acceptable?","also":["When do I accept eventual consistency versus strict consistency?"],"a":["Balances and ledger postings need strong guarantees. Notifications, search views and analytics can lag. State the invariant first, then pick the weakest consistency that protects it.","Strict where a violation causes money, safety or legal harm. Eventual where staleness is invisible or recoverable. Decide from the invariant, not from habit."],"tags":["Consistency","Transactions","Databases"],"legacy":[12,102]},{"id":"give-users-read-writes-reads","cat":"consistency","topic":"Consistency models & CAP","level":"intermediate","source":"both","q":"Give users read-your-writes when reads are served from replicas.","also":["How do I handle read your own writes in a distributed system?"],"a":["Route a user's reads to the primary for a short window, or carry a log position token and wait for replicas to reach it. Compare cost and complexity.","Sticky reads from the primary after a write, session tokens tracking a replica position, or client-side caching of the just-written value."],"tags":["Databases","Consistency"],"legacy":[15,104]},{"id":"model-consistency-levels-across-services","cat":"consistency","topic":"Consistency models & CAP","level":"intermediate","source":"ref","q":"How do I model consistency levels across services and data stores?","also":[],"a":["Decide per data class: strong for money and inventory, read-your-writes for user-facing state, eventual for derived views. Document the guarantee at each service boundary."],"tags":["Consistency"],"legacy":[64]},{"id":"reason-about-cap-trade-offs","cat":"consistency","topic":"Consistency models & CAP","level":"intermediate","source":"ref","q":"How do I reason about CAP trade-offs for a given product requirement?","also":[],"a":["CAP only matters during a partition. For each operation decide whether it must refuse (consistency) or may proceed on stale or divergent data (availability), and what reconciliation follows."],"tags":["Consistency","Reliability"],"legacy":[67]},{"id":"replace-two-phase-commit-across","cat":"consistency","topic":"Distributed transactions & reconciliation","level":"advanced","source":"both","q":"Replace a two-phase commit across three services.","also":["How do I implement distributed transactions without 2PC pain?"],"a":["Saga with compensations, transactional outbox, idempotent consumers. Be honest about what you give up: isolation. Show how a half-finished saga is visible and recoverable.","Sagas with compensating actions, outbox for reliable event emission, idempotent steps, and clear handling for stuck or partially complete flows."],"tags":["Transactions","Messaging"],"legacy":[14,103]},{"id":"design-outbox-inbox-pattern-reliable","cat":"consistency","topic":"Distributed transactions & reconciliation","level":"advanced","source":"ref","q":"How do I design an outbox and inbox pattern for reliable events?","also":[],"a":["Write the event in the same transaction as the state change, relay it to the broker, and dedupe on the consumer with an inbox table keyed by event id. Cover relay lag and ordering."],"tags":["Transactions","Messaging"],"legacy":[65]},{"id":"reconcile-divergent-data-across-systems","cat":"consistency","topic":"Distributed transactions & reconciliation","level":"intermediate","source":"ref","q":"How do I reconcile divergent data across systems?","also":[],"a":["Pick a source of truth per field, run periodic comparison jobs, classify differences, auto-repair the safe ones, and route the rest for review. Track drift as a metric."],"tags":["Transactions"],"legacy":[66]},{"id":"generate-unique-ids-across-regions","cat":"consistency","topic":"Consensus & distributed IDs","level":"intermediate","source":"both","q":"Generate unique IDs across regions without a central counter.","also":["How do I design id generation that works across regions?"],"a":["Snowflake-style, ULID, UUIDv7. Clock skew, sortability, index locality, and what breaks if a node reuses a worker id.","Time-ordered unique ids (Snowflake, ULID, UUIDv7), per-node identifiers, clock skew handling, and index-friendly ordering. Avoid a global counter on the hot path."],"tags":["Consistency","Databases"],"legacy":[16,105]},{"id":"raft-paxos-quorums-gossip-appear","cat":"consistency","topic":"Consensus & distributed IDs","level":"intermediate","source":"both","q":"Where do Raft, Paxos, quorums and gossip appear in a system you would really build?","also":["How do Raft, Paxos, gossip, and quorum based replication actually fit into my design?"],"a":["Coordination and metadata on a consensus log, tunable quorums for data, gossip for membership and failure detection. Show that you use them, not reimplement them.","Explain the guarantee each one provides, what it costs in latency and availability, and where it sits in the design (coordination service, replication layer, membership). Name a real system for each.","Consensus for leader election and metadata, quorum reads and writes for tunable consistency, gossip for membership and failure detection. Use proven implementations."],"tags":["Consistency","Reliability"],"legacy":[17,107,106]},{"id":"list-ways-three-tier-service","cat":"reliability","topic":"Failure modes & degradation","level":"fundamental","source":"both","q":"List the ways a three-tier service fails under real load before drawing any boxes.","also":["What are all the ways my system can fail under real traffic?"],"a":["Slow dependencies, retries, queue growth, GC pauses, connection pool exhaustion, bad deploys, clock drift, partial network partitions. Slow is worse than down.","Overload, slow or failing dependencies, resource exhaustion, bad deploys, data corruption, network partitions, cascading retries, and operator error. Group by blast radius."],"tags":["Reliability","Observability"],"legacy":[18,108]},{"id":"design-graceful-degradation-instead-hard","cat":"reliability","topic":"Failure modes & degradation","level":"fundamental","source":"ref","q":"How do I design for graceful degradation instead of hard failure?","also":[],"a":["Rank features by importance, define a fallback for each dependency (cached, default, hidden), and test the degraded modes. Decide in advance what the user sees."],"tags":["Reliability"],"legacy":[68]},{"id":"retries-amplifying-outage-design-retries","cat":"reliability","topic":"Retries, breakers & bulkheads","level":"intermediate","source":"both","q":"Retries are amplifying an outage. Design retries that do not.","also":["How do I implement retries without causing storms and loops?"],"a":["Retry budgets, exponential backoff with jitter, deadline propagation, retry at one layer only, idempotent operations only, and a kill switch.","Capped attempts, exponential backoff with jitter, retry budgets, deadline propagation, retries at a single layer, and only for idempotent operations."],"tags":["Reliability"],"legacy":[19,109]},{"id":"choose-size-circuit-breakers-bulkheads","cat":"reliability","topic":"Retries, breakers & bulkheads","level":"intermediate","source":"both","q":"Choose and size circuit breakers, bulkheads and timeouts.","also":["How do I design circuit breakers and bulkheads correctly?"],"a":["Timeout below the caller's deadline, bulkhead per dependency, breaker thresholds from observed error rate. Cover half-open probing and fallback behavior.","Breaker opens on error or latency thresholds and probes in half-open state. Bulkheads isolate thread or connection pools per dependency. Tune from measured behavior and test them."],"tags":["Reliability"],"legacy":[20,110]},{"id":"fail-over-between-two-regions","cat":"reliability","topic":"Multi-region & outages","level":"advanced","source":"both","q":"Fail over between two regions without split brain.","also":["How do I run in multiple regions and fail over cleanly?"],"a":["Single writer per partition, fencing tokens, health-based traffic shifting, data loss window (RPO) and recovery time (RTO) stated up front. Practice the failover, do not just draw it.","Active-active or active-passive, a single writer per data partition, replication lag and loss window stated, health-driven DNS or traffic management, and regular failover drills."],"tags":["Reliability","Consistency"],"legacy":[21,111]},{"id":"design-data-center-outage-scenarios","cat":"reliability","topic":"Multi-region & outages","level":"advanced","source":"ref","q":"How do I design for data center outage scenarios?","also":[],"a":["Spread across zones first, then regions. Know your capacity after losing one site, replicate data with a stated loss window, and keep traffic shifting and runbooks tested."],"tags":["Reliability"],"legacy":[69]},{"id":"plan-rollback-release-has-already","cat":"reliability","topic":"Releases & rollback","level":"advanced","source":"both","q":"Plan a rollback for a release that has already migrated data.","also":["How do I design a rollback strategy for bad releases?"],"a":["Backward compatible schema, feature flags, forward-fix versus rollback decision rule, and data written by the new code that the old code must still read.","Canary and progressive rollout, automatic rollback on SLO regression, backward-compatible schemas, feature flags, and a clear rule for rolling back versus fixing forward."],"tags":["Migration","Reliability"],"legacy":[23,112]},{"id":"define-slos-lending-platform-derive","cat":"reliability","topic":"SLOs","level":"advanced","source":"both","q":"Define SLOs for a lending platform and derive alerts from the error budget.","also":["How do I define SLOs and design around them?"],"a":["User-visible indicators such as approval latency and disbursal success. Multi-window burn rate alerts. Link budget exhaustion to a release freeze policy.","Pick user-visible indicators, set targets from user need and cost, track error budget, alert on burn rate, and let budget exhaustion change release behavior."],"tags":["Observability","Reliability"],"legacy":[22,113]},{"id":"make-rebuild-scratch-possible-if","cat":"reliability","topic":"Recovery","level":"advanced","source":"ref","q":"How do I make rebuild from scratch possible if everything is lost?","also":[],"a":["Infrastructure as code, tested backups with restore drills, a replayable event log as source of truth, documented bootstrap order, and a measured recovery time."],"tags":["Reliability","Databases"],"legacy":[71]},{"id":"event-driven-request-response-order","cat":"streaming","topic":"Event-driven design","level":"fundamental","source":"both","q":"Event-driven or request-response for order placement? Decide and defend it.","also":["When do I choose event-driven over request-response?"],"a":["Customer needs an answer now, so the order write is synchronous. Downstream work (fulfilment, notifications) is asynchronous. Say where you need a durable event and where a call is enough.","When producers should not wait or know about consumers, when work can be asynchronous, when many consumers need the same fact, or when you need replay. Not when the caller needs an immediate answer."],"tags":["Messaging","Architecture"],"legacy":[24,114]},{"id":"exactly-once-practice-kafka-flink","cat":"streaming","topic":"Delivery semantics","level":"advanced","source":"both","q":"Exactly-once in practice: what do Kafka and Flink give you, and what do you still own?","also":["How do I handle exactly once versus at least once semantics in practice?"],"a":["Idempotent producers, transactions, checkpointed state. The sink and any external side effect still need idempotency. Be precise: exactly-once processing, not exactly-once delivery.","Assume at-least-once delivery and make consumers idempotent. Use transactional or idempotent producers and checkpointed processing where available, and note that external side effects need their own dedupe."],"tags":["Messaging"],"legacy":[25,116]},{"id":"poison-message-blocks-partition-design","cat":"streaming","topic":"Poison messages & dead letters","level":"advanced","source":"both","q":"A poison message blocks a partition. Design the handling.","also":["How do I avoid processing the same event forever due to poison messages?"],"a":["Bounded retries, retry topics with delay, dead-letter topic with context, alert on DLQ depth, and a safe replay tool. Decide when skipping is acceptable.","Attempt counters, routing to a dead-letter destination after a limit, per-message isolation so one bad record does not block the stream, and alerts for investigation."],"tags":["Messaging","Reliability"],"legacy":[26,119]},{"id":"design-dead-letter-queues-retry","cat":"streaming","topic":"Poison messages & dead letters","level":"intermediate","source":"ref","q":"How do I design dead-letter queues and retry policies?","also":[],"a":["Bounded retries with backoff, delayed retry queues, a dead-letter queue carrying error context, alerting on its depth, and a safe replay path."],"tags":["Messaging","Reliability"],"legacy":[118]},{"id":"keep-ordering-also-need-parallelism","cat":"streaming","topic":"Ordering","level":"advanced","source":"both","q":"Keep ordering when you also need parallelism.","also":["How do I handle ordering of events when it matters?"],"a":["Key by the entity whose order matters, choose partition count for peak consumers, sequence numbers per key, and what happens during rebalance.","Partition by the key whose order matters, sequence numbers for detecting gaps and duplicates, single consumer per partition, and care during rebalances and retries."],"tags":["Consistency","Messaging"],"legacy":[27,120]},{"id":"design-scheduler-millions-delayed-jobs","cat":"streaming","topic":"Schedulers & long-running jobs","level":"advanced","source":"both","q":"Design a scheduler for millions of delayed jobs a day.","also":["How do I design a job scheduler for millions of jobs a day?"],"a":["Time-bucketed storage, a sharded poller with leases, at-least-once execution with idempotent jobs, clock skew, backlog catch-up after an outage.","Sharded time-bucketed storage, workers claiming jobs with leases, idempotent job execution, retry with backoff, and recovery of jobs held by crashed workers."],"tags":["Messaging","Scaling"],"legacy":[28,117]},{"id":"track-status-long-running-jobs","cat":"streaming","topic":"Schedulers & long-running jobs","level":"intermediate","source":"ref","q":"How do I track the status of long-running jobs for users?","also":[],"a":["A job record with state, progress and error, returned immediately with an id. Clients poll or subscribe. Make states resumable and make the record the source of truth, not the queue."],"tags":["Messaging"],"legacy":[72]},{"id":"design-fan-out-fan-pipeline","cat":"streaming","topic":"Schedulers & long-running jobs","level":"advanced","source":"ref","q":"How do I design a fan-out and fan-in pipeline for heavy computations?","also":[],"a":["Split into idempotent tasks, track completion by counter or barrier, handle partial failure and stragglers, and bound concurrency to protect shared resources."],"tags":["Scaling","Messaging"],"legacy":[73]},{"id":"evolve-event-schema-breaking-consumers","cat":"streaming","topic":"Event schema evolution","level":"intermediate","source":"both","q":"Evolve an event schema without breaking consumers.","also":["How do I design an event schema that can evolve safely?"],"a":["Schema registry with compatibility mode, additive changes, tolerant readers, versioned topics only as a last resort, and a deprecation window with consumer inventory.","Schema registry with a compatibility rule, additive-only changes by default, tolerant readers, explicit versioning for breaks, and a plan to retire old versions."],"tags":["Migration","Messaging"],"legacy":[29,115]},{"id":"draw-service-boundaries-lending-platform","cat":"apis","topic":"Service boundaries & gateway","level":"intermediate","source":"both","q":"Draw service boundaries for a lending platform: origination, underwriting, servicing, collections.","also":["How do I define clear boundaries between services?"],"a":["Bound by data ownership and change rate, not by nouns. Decide which data is copied by event and which is queried live. Show where a loan's state machine lives.","One owner per piece of data, interfaces that match business capabilities, low coupling on change, and a test: can a team ship without coordinating with others?"],"tags":["APIs","Architecture"],"legacy":[30,121]},{"id":"design-gateway-evolve-independently-services","cat":"apis","topic":"Service boundaries & gateway","level":"intermediate","source":"both","q":"Design a gateway that can evolve independently of the services behind it.","also":["How do I design a gateway that can evolve independently of services?"],"a":["Keep it thin: routing, auth, limits, observability. No business logic. Config-driven routes, canary support, and its own failure budget.","Thin gateway with routing, auth and limits only, declarative configuration, versioned routes, and no knowledge of service internals."],"tags":["APIs","Architecture"],"legacy":[35,125]},{"id":"version-public-api-cannot-force","cat":"apis","topic":"Versioning, compatibility & deprecation","level":"fundamental","source":"both","q":"Version a public API when you cannot force clients to upgrade.","also":["How do I design versioning for public APIs?","How do I design APIs so they can evolve without breaking clients?"],"a":["Additive changes by default, explicit versions for breaking ones, a support policy with dates, usage telemetry per version, and contract tests.","Additive changes within a version, a new version for breaking changes, a published support policy, usage metrics per version, and clear deprecation dates.","Additive changes only, optional fields with defaults, tolerant readers, explicit versioning for breaks, and contract tests against real client usage."],"tags":["APIs","Migration"],"legacy":[31,122,52]},{"id":"deprecate-endpoint-safely","cat":"apis","topic":"Versioning, compatibility & deprecation","level":"intermediate","source":"both","q":"Deprecate an endpoint safely.","also":["How do I design a safe deprecation process?"],"a":["Find real callers from logs, announce with dates, add Sunset headers, brown-out in staging then production, and keep a path for stragglers.","Identify callers from telemetry, announce with dates, warn in responses, run brownouts, support stragglers, and only then remove."],"tags":["Migration","APIs","Reliability"],"legacy":[34,127]},{"id":"design-backward-compatibility-older-clients","cat":"apis","topic":"Versioning, compatibility & deprecation","level":"intermediate","source":"ref","q":"How do I design for backward compatibility with older clients?","also":[],"a":["Support-window policy, version telemetry, feature negotiation, and server-side shims for the oldest supported clients. Know when you can finally stop supporting one."],"tags":["APIs","Migration"],"legacy":[78]},{"id":"handle-breaking-change-scenarios-minimal","cat":"apis","topic":"Versioning, compatibility & deprecation","level":"intermediate","source":"ref","q":"How do I handle breaking change scenarios with minimal disruption?","also":[],"a":["Run old and new in parallel, migrate clients with tooling and dates, monitor who still calls the old path, and offer a rollback during the cutover."],"tags":["APIs","Migration"],"legacy":[82]},{"id":"design-backward-compatibility-schemas-change","cat":"apis","topic":"Versioning, compatibility & deprecation","level":"intermediate","source":"ref","q":"How do I design for backward compatibility when schemas change?","also":[],"a":["Additive fields, defaults for missing values, never reuse or repurpose a field, readers that ignore unknown fields, and compatibility checks in CI."],"tags":["Migration","APIs"],"legacy":[126]},{"id":"design-per-tenant-rate-limits","cat":"apis","topic":"Rate limits & quotas","level":"intermediate","source":"both","q":"Design per-tenant rate limits that do not punish well-behaved bursty clients.","also":["How do I design tenant-level rate limits and quotas?","How do I design rate limiting that does not break good users?"],"a":["Token bucket with burst allowance, shared counters in a fast store, local approximation to cut round trips, clear 429 responses, and tiered quotas.","Limits per tenant and per plan, burst allowance, shared counters in a fast store, fair sharing under contention, and visibility so tenants see their usage.","Token bucket with burst headroom, limits per identity rather than per IP where possible, clear 429 responses with retry hints, and separate limits for abusive and normal traffic."],"tags":["APIs","Reliability","Scaling"],"legacy":[32,123,101]},{"id":"one-request-fans-out-five","cat":"apis","topic":"Partial failure","level":"advanced","source":"both","q":"One request fans out to five services and two fail. What do you return?","also":["How do I handle partial failures in multi-service calls?"],"a":["Classify calls as required or optional, return degraded results with a marker, set per-call timeouts, never block the whole response on the slowest optional call.","Timeouts per call, required versus optional dependencies, degraded responses, compensations for completed steps, and idempotency so retries are safe."],"tags":["Reliability","APIs"],"legacy":[33,124]},{"id":"should-each-layer-log-must","cat":"observability","topic":"Logging & tracing","level":"fundamental","source":"both","q":"What should each layer log, and what must never be logged?","also":["What should I log at each layer, and what should I never log?"],"a":["Structured logs with a request id at every layer. Never log secrets, tokens, full card numbers or personal data. Sampling for high-volume paths and retention by sensitivity.","Structured logs with correlation ids, entry and exit of requests, errors with context, and decisions. Never secrets, tokens, full payment data or unnecessary personal data."],"tags":["Observability","Cost & compliance","Reliability"],"legacy":[36,128]},{"id":"trace-request-across-50-services","cat":"observability","topic":"Logging & tracing","level":"advanced","source":"both","q":"Trace a request across 50 services without a runaway bill.","also":["How do I design tracing across 50+ microservices?"],"a":["Context propagation everywhere, tail-based sampling that keeps errors and slow traces, span attributes that are queryable, and a budget per team.","Standard context propagation, consistent span naming, tail-based sampling to keep slow and failed traces, and links from metrics and logs to traces."],"tags":["Observability","Cost & compliance"],"legacy":[37,129]},{"id":"alert-user-pain-not-noise","cat":"observability","topic":"Metrics, dashboards & alerts","level":"intermediate","source":"both","q":"Alert on user pain, not on noise.","also":["How do I design alerting that catches real issues but avoids noise?"],"a":["Page on symptoms such as error rate and latency against SLOs, ticket on causes. Every page needs an owner and a runbook link. Delete alerts that nobody acted on.","Alert on user-facing symptoms and SLO burn, attach runbooks, deduplicate and group, review noisy alerts regularly, and delete the ones that never lead to action."],"tags":["Observability","Reliability"],"legacy":[39,130]},{"id":"design-metrics-actually-tell-me","cat":"observability","topic":"Metrics, dashboards & alerts","level":"intermediate","source":"ref","q":"How do I design metrics that actually tell me system health?","also":[],"a":["Latency, traffic, errors and saturation per service and per dependency, with histograms rather than averages and business metrics alongside technical ones."],"tags":["Observability"],"legacy":[83]},{"id":"design-dashboards-help-during-incidents","cat":"observability","topic":"Metrics, dashboards & alerts","level":"intermediate","source":"ref","q":"How do I design dashboards that help during incidents?","also":[],"a":["One top-level health view, then drill-down by service and dependency. Put symptoms first, show deploy markers, and keep the layout the same across services."],"tags":["Observability","Operations"],"legacy":[84]},{"id":"p50-flat-but-p99-doubled","cat":"observability","topic":"Latency debugging","level":"advanced","source":"both","q":"p50 is flat but p99 doubled. How do you debug it?","also":["How do I debug high tail latency in a distributed system?"],"a":["Look for queueing, GC, noisy neighbors, a slow shard, retries, lock contention. Compare by instance, endpoint and dependency. Use exemplars to jump from a metric to a trace.","Compare percentiles by instance, endpoint and dependency, look for queueing, GC, retries and hot shards, and use traces to find the slow span. Hedged requests can mask but not fix it."],"tags":["Latency","Observability"],"legacy":[38,131]},{"id":"rehearse-failure-before-production","cat":"observability","topic":"Runbooks & failure drills","level":"intermediate","source":"both","q":"Rehearse failure before production does it for you.","also":["How do I simulate failures before they hit production?"],"a":["Game days, dependency fault injection, region evacuation drills, restore-from-backup tests. Start in staging with a hypothesis and a stop condition.","Fault injection for dependencies and infrastructure, game days, load and soak tests, and restore drills, starting with a hypothesis and a clear abort condition."],"tags":["Reliability","Observability"],"legacy":[40,133]},{"id":"write-runbook-call-engineer-follow","cat":"observability","topic":"Runbooks & failure drills","level":"fundamental","source":"both","q":"Write a runbook the on-call engineer can follow at 3 a.m.","also":["How do I design runbooks so on-call engineers can act fast?"],"a":["Symptom first, then checks in order, then safe actions with exact commands, then when to escalate. Tested by someone who did not write it.","Start from the alert, give ordered checks, exact commands, safe mitigations, escalation paths, and keep them tested and reviewed after incidents."],"tags":["Operations","Observability","Reliability"],"legacy":[41,132]},{"id":"design-something-mvp-first-still","cat":"evolution","topic":"MVP, platforms & cost","level":"fundamental","source":"ref","q":"How do I design something MVP-first that can still grow?","also":[],"a":["Make the cheapest design that satisfies today's load, but keep the seams that are expensive to add later: identifiers, data ownership, API contracts and observability."],"tags":["Scaling","Architecture"],"legacy":[74]},{"id":"choose-between-building-platform-one","cat":"evolution","topic":"MVP, platforms & cost","level":"intermediate","source":"ref","q":"How do I choose between building a platform and a one-off service?","also":[],"a":["Build a platform when three or more teams need the same capability and the interface is stable. Otherwise ship the one-off and extract later from real usage."],"tags":["Architecture"],"legacy":[75]},{"id":"design-cost-visibility-optimization-day","cat":"evolution","topic":"MVP, platforms & cost","level":"intermediate","source":"ref","q":"How do I design for cost visibility and optimization from day one?","also":[],"a":["Tag every resource by team and service, expose cost per request or per tenant, set budgets and alerts, and review the top spenders on a schedule."],"tags":["Cost & compliance","Observability"],"legacy":[76]},{"id":"decide-buy-build","cat":"evolution","topic":"Build vs buy","level":"intermediate","source":"both","q":"Decide what to buy and what to build.","also":["How do I decide what to buy versus what to build?"],"a":["Build what differentiates you and what you must control. Buy commodity. Count integration, lock-in, data egress and the people cost of running either.","Build what differentiates you or needs deep control. Buy commodity capability. Weigh lock-in, integration cost, data portability, and the ongoing cost of operating either choice."],"tags":["Architecture","Cost & compliance"],"legacy":[47,140]},{"id":"design-systems-multiple-teams-safely","cat":"evolution","topic":"Extensibility, experiments & compliance","level":"advanced","source":"ref","q":"How do I design systems that multiple teams can safely extend?","also":[],"a":["Clear extension points, stable contracts, isolation so one team's plugin cannot take down others, and ownership documented per component."],"tags":["Architecture","Leadership"],"legacy":[77]},{"id":"plan-data-residency-regional-regulations","cat":"evolution","topic":"Extensibility, experiments & compliance","level":"intermediate","source":"ref","q":"How do I plan for data residency and regional regulations?","also":[],"a":["Tag data by jurisdiction, pin storage and processing to regions, control cross-region replication and logs, and design deletion and access requests per region."],"tags":["Cost & compliance","Reliability"],"legacy":[79]},{"id":"design-support-experiments-such-as","cat":"evolution","topic":"Extensibility, experiments & compliance","level":"intermediate","source":"ref","q":"How do I design to support experiments such as A/B tests and flags cleanly?","also":[],"a":["Central flag service with stable user bucketing, exposure logging, kill switches, and a cleanup process for dead flags. Keep experiment logic out of business code paths where possible."],"tags":["Architecture"],"legacy":[80]},{"id":"design-migration-paths-legacy-system","cat":"evolution","topic":"Legacy migration","level":"advanced","source":"ref","q":"How do I design migration paths when the legacy system cannot just die?","also":[],"a":["Strangler pattern: route slices of traffic to the new system, keep both in sync during the overlap, migrate data by domain, and define an exit criterion for the old system."],"tags":["Migration","Architecture"],"legacy":[81]},{"id":"defend-design-trade-off-skeptical","cat":"judgment","topic":"Trade-offs & design reviews","level":"intermediate","source":"both","q":"Defend a design trade-off to a skeptical architect in five minutes.","also":["How do I defend trade-offs to a sceptical architect?"],"a":["State the constraint, the options you rejected and why, what would change your mind, and how you will find out cheaply if you are wrong.","State requirements and constraints, show alternatives with costs, say what you are giving up, and name the signal that would make you reverse the decision."],"tags":["Leadership","Architecture"],"legacy":[42,134],"answer":{"thesis":"Lead with the constraint, not the design. A skeptic is persuaded by seeing that you considered their option, priced your own downside honestly, and know what evidence would change your mind.","pitch":"I'd spend the first minute restating the requirement and the one or two constraints that drive the decision, for example p99 under 100 ms and a team of four, and check we agree on them. Then the decision in one sentence. Then the alternatives I rejected, including the one the architect probably prefers, each with the specific reason it lost against those constraints. Then what we're giving up, said plainly before they have to point it out. I'd close with the trigger that would make me reverse the decision and how cheaply we'll detect it: a metric, a load test, a date. If they still disagree, I'd ask which constraint they weigh differently, because that's usually where the real disagreement is.","points":[{"h":"Agree on the problem first","d":"Restate the requirement and the deciding constraints and get a nod. Many design arguments are really disagreements about requirements, and they dissolve once that's surfaced."},{"h":"State the decision in one sentence","d":"For example: 'One Postgres primary with read replicas, not a distributed SQL database.' A crisp claim is easier to examine than a diagram."},{"h":"Steelman the alternatives","d":"Present the skeptic's preferred option at its strongest, then show why it loses on these constraints: cost, team skills, latency, timeline. Strawmanning it loses the room immediately."},{"h":"Name your costs before they do","d":"'This caps us at roughly X writes per second and means a migration in about 18 months if growth holds.' Saying it first removes the gotcha and shows you've done the arithmetic."},{"h":"Show how reversible it is","d":"Distinguish one-way doors (data model, public API, deep vendor lock-in) from two-way doors. Point to the seams that make reversal cheaper: an interface boundary, an export path."},{"h":"Set kill criteria","d":"A measurable trigger, an owner and a check date. 'If p99 write latency exceeds 50 ms at peak or we pass 5 TB, we revisit.' That turns the debate into a plan."},{"h":"Find the crux if you still disagree","d":"Locate the specific assumption you differ on (growth rate, failure tolerance, team size) and propose a cheap experiment to settle it. If it's their call, record the reasoning and commit."}],"decision":"Push hard on one-way doors; concede quickly on two-way doors where trying is cheaper than arguing. A disagreement about facts needs data; a disagreement about values (cost against safety, speed against flexibility) needs a decider.","numbers":["A five-minute shape: about 1 minute on problem and constraints, 30 seconds on the decision, 2 minutes on alternatives and costs, 1 minute on reversal criteria, the rest for questions."],"pitfalls":["Defending the diagram instead of the decision: reasons persuade, boxes don't.","Strawmanning the alternative; the skeptic notices and stops listening.","Hiding the downside and letting them find it.","Treating it as a contest: being right while leaving the architect unheard costs you the next review.","Unfalsifiable claims such as 'it will scale' instead of a number and a test."],"followups":[{"q":"What would make you change your mind?","a":"Have a specific answer ready: a metric threshold, a requirement change or a test result, plus when you'll check it."},{"q":"Why not just use X? Everyone does.","a":"Acknowledge where X is genuinely better, then tie your choice back to the constraints. Popularity is evidence about ecosystem and hiring, which you can price, not a reason on its own."},{"q":"I'm the approver and I think you're wrong.","a":"Ask which constraint they weigh differently, record the decision and its rationale, and commit. If the decision is reversible, propose a checkpoint to revisit it with data."}],"example":"Proposing a modular monolith instead of microservices for a new lending product, with a team of six and a nine-month deadline. The architect preferred services for future scale. The defence conceded that independent scaling and deploys were being given up, showed module boundaries drawn along the future service lines, and set a trigger: split a module out when its team or deploy cadence diverges from the rest.","related":["review-peer-s-design-deeply","tell-design-over-engineered","write-design-doc-still-useful","decide-buy-build"],"sources":[{"title":"Michael Nygard: Documenting architecture decisions","url":"https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions"}]}},{"id":"review-peer-s-design-deeply","cat":"judgment","topic":"Trade-offs & design reviews","level":"advanced","source":"both","q":"Review a peer's design deeply and still be easy to work with.","also":["How do I review someone else's design deeply but respectfully?"],"a":["Ask questions that expose assumptions, separate blocking concerns from preferences, propose an alternative when you object, and credit what is good.","Understand the goal first, ask questions about failure and scale, separate must-fix from preference, suggest alternatives, and acknowledge what is solid."],"tags":["Leadership"],"legacy":[46,136]},{"id":"explain-design-junior-developer-they","cat":"judgment","topic":"Trade-offs & design reviews","level":"intermediate","source":"ref","q":"How do I explain my design to a junior developer so they truly get it?","also":[],"a":["Start from the problem and one request path, add pieces only as the problem demands them, use a single diagram, and check understanding by asking them to predict a failure."],"tags":["Leadership"],"legacy":[85]},{"id":"tell-design-over-engineered","cat":"judgment","topic":"Simplicity & over/under-engineering","level":"intermediate","source":"both","q":"How do you tell when a design is over-engineered?","also":["How do I know when a design is over-engineered?"],"a":["Components with no current requirement behind them, flexibility nobody has asked for, more moving parts than people to run them.","Complexity without a current requirement, abstractions with one user, more services than teams, and anything you cannot explain the need for in a sentence."],"tags":["Leadership","Architecture"],"legacy":[43,137]},{"id":"tell-design-dangerously-under-engineered","cat":"judgment","topic":"Simplicity & over/under-engineering","level":"intermediate","source":"both","q":"How do you tell when a design is dangerously under-engineered?","also":["How do I know when a design is dangerously under-engineered?"],"a":["No answer for the failure you can name, no way to roll back, no capacity numbers, one person who understands it.","No failure handling for known risks, no capacity estimate, no rollback or recovery path, unclear ownership, and a single point of failure on a critical path."],"tags":["Leadership","Reliability"],"legacy":[44,138]},{"id":"simplify-complex-design-losing-guarantees","cat":"judgment","topic":"Simplicity & over/under-engineering","level":"advanced","source":"ref","q":"How do I simplify a complex design without losing guarantees?","also":[],"a":["List the guarantees that must hold, remove components that do not protect one, merge things that always change together, and prove the invariants still hold."],"tags":["Leadership","Reliability"],"legacy":[86]},{"id":"design-boring-reliability-instead-cleverness","cat":"judgment","topic":"Simplicity & over/under-engineering","level":"intermediate","source":"ref","q":"How do I design for boring reliability instead of cleverness?","also":[],"a":["Choose proven components, minimize moving parts, prefer simple failure modes, and spend novelty budget only where it creates real advantage."],"tags":["Leadership","Reliability"],"legacy":[88]},{"id":"decide-not-build-system","cat":"judgment","topic":"Simplicity & over/under-engineering","level":"intermediate","source":"ref","q":"How do I decide what not to build into a system?","also":[],"a":["Tie each feature to a present requirement or measured risk, defer what is cheap to add later, and write the non-goals down."],"tags":["Leadership","Architecture"],"legacy":[89]},{"id":"design-mistakes-cheap-not-catastrophic","cat":"judgment","topic":"Simplicity & over/under-engineering","level":"advanced","source":"ref","q":"How do I design so that mistakes are cheap, not catastrophic?","also":[],"a":["Small blast radius, progressive rollout, reversible changes, backups and restore tests, feature flags, and guardrails on destructive operations."],"tags":["Reliability","Leadership"],"legacy":[139]},{"id":"write-design-doc-still-useful","cat":"judgment","topic":"Design docs & ownership","level":"advanced","source":"both","q":"Write a design doc that is still useful in three years.","also":["How do I write a design doc that survives 3 years of evolution?"],"a":["Context and constraints, alternatives considered, decisions with reasons, non-goals, and open questions. The reasons age better than the diagrams.","Record context, goals and non-goals, alternatives considered, decisions and their reasons, and known risks. Date it, link follow-ups, and keep diagrams simple."],"tags":["Leadership"],"legacy":[45,135]},{"id":"design-systems-owned-teams-not","cat":"judgment","topic":"Design docs & ownership","level":"advanced","source":"ref","q":"How do I design systems that can be owned by teams, not heroes?","also":[],"a":["Documented runbooks, shared on-call, boring technology, clear ownership boundaries, and no component only one person understands."],"tags":["Leadership","Operations"],"legacy":[87]}]};
